pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;

    function setUp() public { c = new PuttyV2("", 0, address(this)); }

    function testFuzz_property(bool isCall, uint256 duration) public {
        duration = bound(duration, 0, 9999 days);

        DummyToken token = new DummyToken();
        ERC1271Signer maker = new ERC1271Signer();

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);
        uint256[] memory floorAssetTokenIds = new uint256[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: isCall,
            isLong: true,
            baseAsset: address(token),
            strike: 0,
            premium: 0,
            duration: duration,
            expiration: block.timestamp + 1000,
            nonce: 0,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bool ok;
        try c.fillOrder(order, "", floorAssetTokenIds) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "fillOrder must succeed");

        bytes32 orderHash = c.hashOrder(order);
        uint256 key = uint256(orderHash); // order.isLong == true

        // single deciding assertion
        assertTrue(c.positionExpirations(key) == block.timestamp + duration, "expiration must be exact duration");
    }
}

